<?php
/** TEMP PS S1676 run q — DP pakai: av-source v1.2 + av-reduce v1.2 DEPLOY + snippet 567 v1.3 (D); testai resolve + E2E mazinti/grazinti (T). */
add_action('init', function(){
  if (!isset($_GET['ps_s1676q'])) return; global $wpdb; $p=$wpdb->prefix; $F=$_GET['ps_s1676q']; $o=array('v'=>'S1676 q','faze'=>$F);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $bk=wp_upload_dir()['basedir'].'/ps-backups/';
  if($F==='D'){
    $F2=array('petshop-av-source.php'=>array('','11750e14be57cd7ebc93457141233a79'),'petshop-av-reduce.php'=>array('','becc48441f03a1094795a47b2d546d73'));
    $rasyti=array();
    foreach($F2 as $n=>$x){ $f=WPMU_PLUGIN_DIR.'/'.$n; $k=base64_decode($x[0]); if(md5_file($f)!==$x[1]){ $o['STOP']=$n.' gyvas md5 kitoks: '.md5_file($f); break; } if(@token_get_all($k,TOKEN_PARSE)===false){ $o['STOP']=$n.' sintaksė'; break; } $rasyti[$n]=$k; }
    if(empty($o['STOP'])){ foreach($rasyti as $n=>$k){ $f=WPMU_PLUGIN_DIR.'/'.$n; copy($f,$bk.$n.'.bak_s1676'); file_put_contents($f,$k); $o['md5'][$n]=md5_file($f); }
      $r=wp_remote_get(home_url('/?ps_ping_s1676q='.time()),array('timeout'=>25,'sslverify'=>false)); $c=is_wp_error($r)?'ERR':wp_remote_retrieve_response_code($r); $o['ping']=$c;
      if(is_wp_error($r)||$c>=500){ foreach($rasyti as $n=>$k){ copy($bk.$n.'.bak_s1676',WPMU_PLUGIN_DIR.'/'.$n); } $o['ROLLBACK']=1; }
      else { $s=$wpdb->get_row("SELECT code FROM {$p}snippets WHERE id=567",ARRAY_A); if(md5($s['code'])==='bfb52db946810f516847b368408cda5c'){ file_put_contents($bk.'snippet-567.bak_s1676.php',$s['code']); $o['s567']=$wpdb->update("{$p}snippets",array('code'=>base64_decode(''),'name'=>'Petshop Daugiau=Pigiau Stock Sync v1.3'),array('id'=>567)); wp_cache_flush(); } else $o['s567']='PRALEISTA md5 '.md5($s['code']); } }
  }
  if($F==='T'){
    $o['s567_md5']=md5($wpdb->get_var("SELECT code FROM {$p}snippets WHERE id=567")); $o['s567_name']=$wpdb->get_var("SELECT name FROM {$p}snippets WHERE id=567");
    foreach(array(array(35840,1),array(35840,2),array(35096,1),array(35096,2),array(17707,1)) as $x){ $r=Petshop_AV_Source::resolve($x[0],$x[1]); $o['resolve'][$x[0].'x'.$x[1]]=array($r['source'],$r['av_qty'],$r['av_uztenka'],$r['reason']); }
    // E2E: testinis užsakymas su DP paku 35840 (bazinė 17707, ×8) — mazinti / grazinti / ištrinti; jokių statuso keitimų (laiškų nėra)
    $pries=array('own'=>get_post_meta(17707,'_own_stock_qty',true),'stock'=>get_post_meta(17707,'_stock',true));
    $w=wc_create_order(array('status'=>'pending')); $w->update_meta_data('_petshop_test','s1676q'); $iid=$w->add_product(wc_get_product(35840),1); $it=$w->get_item($iid); $it->update_meta_data('_ps_source','av'); $it->save(); $w->set_billing_email('test-s1676@petshop.lt'); $w->save();
    Petshop_AV_Reduce::mazinti($w->get_id()); $w=wc_get_order($w->get_id()); $it=$w->get_item($iid);
    $po=array('own'=>get_post_meta(17707,'_own_stock_qty',true),'stock'=>get_post_meta(17707,'_stock',true),'rq'=>$it->get_meta('_ps_av_reduced_qty'),'rp'=>$it->get_meta('_ps_av_reduced_pid'),'zym'=>$w->get_meta('_ps_av_reduced'));
    Petshop_AV_Reduce::grazinti($w->get_id());
    $po2=array('own'=>get_post_meta(17707,'_own_stock_qty',true),'stock'=>get_post_meta(17707,'_stock',true),'zym'=>wc_get_order($w->get_id())->get_meta('_ps_av_restored'));
    $notes=array(); foreach(wc_get_order_notes(array('order_id'=>$w->get_id())) as $n) $notes[]=mb_substr($n->content,0,160);
    $oid=$w->get_id(); wc_get_order($oid)->delete(true); $o['e2e']=array('oid'=>$oid,'pries'=>$pries,'po_mazinti'=>$po,'po_grazinti'=>$po2,'pastabos'=>$notes,'istrintas'=>!wc_get_order($oid),'ok'=>($pries['own']===$po2['own'] && (int)$po['own']===(int)$pries['own']-8 && $pries['stock']===$po2['stock']));
    // stebėjimas: AV_Stock log lentelė (jei yra) — paskutiniai 2 įrašai 17707
    $o['av_log']=$wpdb->get_results("SELECT option_value v FROM {$p}options WHERE option_name LIKE 'ps_av_stock_log%' LIMIT 1",ARRAY_A);
  }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
});
